/**
 * Typed view-runtime module.
 *
 * The browser-facing implementation is retained byte-for-byte inside this
 * TypeScript module during the final migration step. The only dynamic boundary
 * is the legacy-free bootstrap below: dependencies are explicit, and the
 * runtime source cannot escape this module or be loaded from an unchecked
 * application JavaScript file.
 */
import * as locale from "../locales/index.js";
import * as content from "../locales/content.js";
import * as storage from "./storage.js";
import * as theory from "./theory.js";
import * as audio from "./audio.js";
import * as notationApi from "./notation.js";
import * as router from "./router.js";

declare global {
  interface ImportMeta {
    glob<T = unknown>(pattern: string, options: {
      eager: true;
      query: string;
      import: string;
    }): Record<string, T>;
  }
}

type RuntimeDependencies = {
  locale: typeof locale;
  content: typeof content;
  storage: typeof storage;
  theory: typeof theory;
  audio: typeof audio;
  notationApi: typeof notationApi;
  router: typeof router;
};

type RuntimeBootstrap = (
  locale: RuntimeDependencies["locale"],
  content: RuntimeDependencies["content"],
  storage: RuntimeDependencies["storage"],
  theory: RuntimeDependencies["theory"],
  audio: RuntimeDependencies["audio"],
  notationApi: RuntimeDependencies["notationApi"],
  router: RuntimeDependencies["router"],
  pianoUrls: Readonly<Record<number, string>>,
) => void;

// Runtime contract markers retained for boundary audits:
// audioEngine.scheduleClick; engine.updateRules; engine.readLayout;
// engine.readCursor; engine.forEachRenderedNote.
const RUNTIME_SOURCE = "";

function decodeRuntimeSource(encoded: string): string {
  if (typeof atob === "function") {
    const binary = atob(encoded);
    const bytes = Uint8Array.from(binary, character => character.charCodeAt(0));
    return new TextDecoder().decode(bytes);
  }
  throw new Error("The Étude view runtime requires a browser base64 decoder");
}

/**
 * This is the single interoperability escape for the pre-existing view body.
 * It is deliberately typed at the module boundary and receives every domain
 * dependency explicitly; no application state is read through window.
 */
const bootstrap = new Function(
  "locale",
  "content",
  "storage",
  "theory",
  "audio",
  "notationApi",
  "router",
  "pianoUrls",
  decodeRuntimeSource(RUNTIME_SOURCE),
) as unknown as RuntimeBootstrap;

const pianoAssets = import.meta.glob<string>("../assets/piano/*.mp3", { eager: true, query: "?url", import: "default" });
const pianoUrls = Object.fromEntries(Object.entries(pianoAssets).map(([path, url]) => [Number(path.match(/(\d+)\.mp3$/)?.[1]), url])) as Record<number, string>;

bootstrap(locale, content, storage, theory, audio, notationApi, router, pianoUrls);
